#define R_SHUNT       0.01f    // 采样电阻 0.01Ω
#define OP_GAIN        8        // PGA增益8（16会因偏置0.2V导致输出饱和，见opamp.c注释）
// ADC参考电压：VREF+(MCU pin28)接3V3_REF网络，硬件已修到3.3V。
#define ADC_VREF       3.3f
#define ADC_RESOLUTION 4096     // ADC分辨率12位
// 零电流偏置不再用固定常数，改为开机自动标定（见main中的[Calib]段），三相各自独立
#define CURRENT_SCALE  (R_SHUNT * OP_GAIN)  // 电流计算系数 = 0.08 V/A
// 低边分流测的是"从地流进相节点"的电流，与"从逆变器流入电机"的标准正方向相反，
// 需要取反，否则FOC的负反馈会变成正反馈、PI直接发散。
#define CURRENT_SIGN   (-1.0f)
#define VBUS_DIVIDER   13.4f    // 母线分压比: (R5 12.4K + R8 1K) / R8 1K

// 置1：开机后进入霍尔自检（死循环，不驱动电机，安全）。手动转轴观察六个状态是否按序出现。
// 纯接线诊断工具，跟正常运行互斥，换新硬件/换线时用得上，留着。
// 磁极对数测量(pulse_cnt)已经用完并确认为26(见MOTOR_POLE_PAIRS说明)，改回0
// 恢复正常FOC_Run()路径。
#define HALL_SELF_TEST     0

// ===== FOC 电流环 =====
// 双PI闭环：Id→0（消除无用的励磁电流），Iq→转矩给定。
// 控制周期 = PWM周期 = 50us，跑在ADC注入转换完成中断里。
#define FOC_TEST           1
#define FOC_IQ_REF         1.0f     // 转矩电流给定(A)，纯电流环调试/波形观察用
#define FOC_ID_REF         0.0f     // 励磁电流给定，FOC恒为0
// 电流环增益，按 Kp=ωc·L 估算(ωc≈2π×300Hz，相电感约0.5mH)保守取值
#define FOC_KP             0.020f   // 电流环比例增益（电压标幺/安培）
#define FOC_KI             0.0005f  // 电流环积分增益（每个控制周期累加）
// 电压限幅，只管电压天花板(电流由PI调到给定值，过流保护兜底)。
// 0.20时空载会把Vq顶死在反电动势上、电流环失去调节余量，抬到0.45留出余量；
// 副作用是空载转速也会同步上升，根治需要外环速度限制。
#define FOC_VLIM           0.45f
// ===== 速度环 =====
// 纯转矩控制+空载没有稳态转速(电机一直加速到反电动势吃光电压为止)，
// 必须有外环把转速摁住。被控对象基本是纯积分，实测空载加速度
// a≈7700(eRPM/s)/A，按闭环带宽ωc≈2π×2Hz(比电流环慢一个数量级以上，
// 避免和电流环/60°霍尔量化耦合出振荡)反推 Kp=ωc/a≈0.0016，取一半更保守。
#define FOC_SPEED_LOOP     1
#define FOC_SPEED_REF_ERPM 3000.0f   // 目标电转速(eRPM)。机械转速 = eRPM/MOTOR_POLE_PAIRS
#define FOC_SPEED_KP       0.0008f   // A / eRPM
#define FOC_SPEED_KI       0.0006f   // A / (eRPM·s)
// 阶跃测试证明这组增益响应快、基本零超调。稳态残留±300~500eRPM纹波是
// 霍尔60°量化+单次跳变测速本身的噪声，加额外低通滤波反而吃掉相位裕度、
// 引发真实振荡，故不再处理，保持现状。
// 速度环输出的转矩电流上限，分两档：
//   近零速危险区：0.4A。反转过零(已经在转、只是调头)表现最干净、扇区
//     读数不畸变，代价是这个值单独拿来当"全局唯一上限"时，正常运行/
//     夹持力矩也被一起拖累——实测手能轻松捏停/挡住电机，对夹爪应用
//     来说这个上限本身就是个bug，不是"保守但能用"。
//   远离零速的正常区：FOC_SPEED_IQ_MAX_NORMAL，给实际运行/夹持力矩用。
// 危险区之所以要压低，是因为静止/近零速时攒的转矩越多，卡滞松开那一下
// 释放的能量越大(机械冲击)；远离零速时不存在"攒能量再突然释放"这个
// 机制，正常按目标力矩给就行，压低反而没有意义。
// 第一版按|eRPM|判定危险区(FOC_IQ_CAP_ZONE_ERPM=1200)，堵住了过流跳闸，
// 但实测发现一个死结：这个判据是"手一使劲把电机压慢，eRPM掉下去，
// 立刻被判定成危险区，上限反而缩回0.4A"——手越用力、允许的转矩越小，
// 完全违背"该顶得住"的直觉，对"手主动按停/顶住不让转"这种场景基本无效。
// 根子是单看瞬时转速分不清两种情况：反转过零(target在远处、实测还没
// 追上，真的有"攒转矩-突然释放"的机械冲击风险) vs 被外力顶在原地但
// 目标本来就在附近(比如就是要停在这、只是有人去掰它，此时并不存在
// "攒能量突然释放"这个机制，追不上的量本来就不大)。这两种在瞬时转速
// 上长得一样，但需要的策略正好相反，判据必须换成能分辨这两者的量。
// 改用"目标-实测"的误差(err)来判定，而不是转速本身：err一直很小
// (说明实测持续跟得上目标，没有攒起来的落差，不管是巡航还是被顶在
// 原地悬停都算)才判定为"已稳定"、放开高上限；err大(不管是反转阶跃
// 刚甩出去、还是被外力硬顶在离目标很远的地方追不上)一律留在危险区、
// 用低上限，因为err大就意味着有个"一旦追上就要猛冲"的落差存在。
// 要求err持续小一段时间(FOC_IQ_SETTLE_MS)而不是单次达标，避免反转
// 途中err短暂穿过0那一下就被误判成"已稳定"。
#define FOC_SPEED_IQ_MAX          0.4f   // 未稳定(危险区)的转矩上限(A)
#define FOC_SPEED_IQ_MAX_NORMAL   1.2f   // 已稳定时的转矩上限(A)，正常运行/夹持力矩用
// ↓↓↓ 用户主导决策：位置环"分成好几个台阶"的根子被坐实为"沿途分布着
// 多个各自独立的齿槽卡点，每一个都要单独触发一轮卡滞助推/giveup才能
// 压过"，不是"同一次挣脱后面没接上气"——之前两版"挣脱后单向续航"改的
// 都是错的时间窗口(只覆盖某一次挣脱之后的一小段，覆盖不了沿途后面
// 全新出现的卡点，实测确认"基本没什么改善")。这次改成直接提高位置环
// "未到位、持续运行"这整段期间的基线转矩本身(取代下面"!pos_arrived时
// 钉死FOC_SPEED_IQ_MAX(0.4A)"那一行)，让沿途大多数齿槽卡点在还没被
// stall_kicking/giveup这类"事后诊断"的机制抓到之前，就已经被这个更高
// 的持续转矩正面压过去，从根上减少stall触发次数本身，而不是让每次
// 触发之后的收尾更漂亮。
// 这直接碰了本session一直守着没动过的安全线(FOC_SPEED_IQ_MAX危险区
// 上限)——过去所有"提高转矩"的改动都刻意避开这条线，只在很窄的时间
// 窗口/单一方向做局部放宽(kick_exit_hold、breakout_pulldown等)。取值
// 跟giveup_iq(0.5A)同一个量级，不是新引入未验证过的数值。
// ↓↓↓ 上机验证暴露回归(第一次)：iq_cap是双向对称钳位，整体抬高0.4A->
// 0.5A让"冲过头->反向修正"这个本来就存在的倾向两头都被放大，"往回迈步"
// 比之前更明显；同时也没能验证出"减少stall触发次数"这个预期效果，台阶
// 感依旧。当时先撤回到0.4A。
// ↓↓↓ 后续排查：把"挣脱后单向续航"(kick_exit_hold，同样是0.5A量级)和
// "脱困速度软上限"/"碎步压制"这三层全部临时关掉(FOC_FRAGSTEP_DISABLE_
// DIAG/FOC_BREAKOUT_DISABLE_DIAG/FOC_KICK_EXIT_HOLD_MS=0)之后，台阶感
// 依旧跟之前差不多——说明这三层不是台阶的成因，根子确实在"0.4A基线压不
// 过沿途齿槽卡点、只能靠突发式kick/giveup"这个更底层的机制。也就是说
// 第一次测试"抬高基线"时，kick_exit_hold(同样0.5A)可能跟这次的抬高
// 同时生效、力度叠加，"往回迈步"不一定是"抬高基线"这个思路本身的问题。
// ↓↓↓ 二次验证(单独测试，其它三层确认关闭、排除干扰)：往回迈步依旧
// 出现——排除了"跟kick_exit_hold叠加"这个假设，坐实"往回迈步"是抬高
// 对称iq_cap这个动作本身直接导致的，不是哪次意外叠加。iq_cap对称约束
// 着PI输出的正负两侧，只要抬高它，"冲过头->反向修正"这个系统本来就有
// 的倾向就会两头一起被放大，跟有没有别的机制同时生效无关。撤回到
// 0.4A，"直接抬高对称基线转矩"这条路到此为止，不再重试同一个方向。
#define FOC_POS_TRANSIT_IQ_MAX   0.4f    // 已撤回(二次验证后确认)，等于FOC_SPEED_IQ_MAX
#define FOC_IQ_SETTLE_ERR_ERPM    300.0f // |目标-实测|低于这个值才算"跟上了"
#define FOC_IQ_SETTLE_MS          600U   // "跟上了"要持续这么久才判定为已稳定、放开高上限
// ↓↓↓ 曾试过"减速方向豁免"：err和erpm_now符号相反(说明实测已经冲过头、
// 目标正要往回拉)时不等settle计时、直接放开到高上限，理论依据是"刹车
// 方向只消耗动能、不是追赶型的猛冲风险"。上机复测证伪：pos游荡范围从
// 原来最坏约9700°扩大到25994°/35593°这个量级，还出现Id瞬时冲到5.37A
// 这种D/Q解耦假设失效的迹象——说明"刹车方向天然安全"这个假设不成立，
// 提前解锁的转矩没有把系统更快摁停，反而在更多场景里被误判成"刹车"
// 从而被放行，实际效果是整个系统跑得更猛更不稳定。已改回原样，"pos
// 不收敛"这个问题需要换别的思路，不能再走"放宽这个方向转矩上限"这条路。
// 起步/破卡滞用的临时高上限：卡住超FOC_STALL_ARM_MS才判定为真卡住(不是
// 过零时的正常短暂停留)，触发条件是"卡住时长"而不是单次瞬时测速，天然
// 带去抖。放宽后周期性"顶一段、歇一段"重试(而不是试一次就永久放弃)，
// 因为慢斜坡下卡住阶段可能远超一次尝试的时长，一次性额度会在爬坡早期
// 就用掉、后面没有第二次机会，实测卡死到需要手动辅助才能继续。
// ↓↓↓ 加了FOC_HallEdge()里的卡滞挣脱急停(见FOC_BREAKAWAY_*)之后复测：
// 急停确实按设计触发了(挣脱瞬间foc_iq_ref被清零)，但sector width畸变
// /大eRPM尖峰基本没改善。原因是急停只能拦住"挣脱之后继续加速"，拦不住
// "已经攒下的动能"——转子在卡住期间已经被顶到0.8A顶了最长1.5秒，这部分
// 能量在挣脱那一刻已经灌进去了，急停反应再快也是马后炮，真正决定挣脱
// 这一下多猛的是"卡住期间攒了多少转矩"，不是"挣脱之后拦得多快"。把
// 上限和每轮顶的时长都往下调，直接压低能攒的能量上限，而不是继续在
// 挣脱之后的反应速度上做文章。
// ↓↓↓ 降到0.6A/800ms之后复测：sector width畸变的频率明显下降(大部分
// 窗口已经是正常60°附近的分布)，但eRPM尖峰仍然频繁打到±3000钳位——
// 说明方向对但幅度不够，"顶一段"这一段本身还是太长，够摸到强静摩擦的
// 上限。继续压缩单轮"顶"的时长(而不是再降电流，电流太低会顶不动、
// 退化成上面注释里说过的"卡死到需要手动辅助")，靠更短、更频繁的
// 尝试替代一次顶到底——单次可能攒的转矩·时间进一步下降，挣脱不了
// 就退回歇一轮，下一轮再试，不影响"最终能顶动"这个目标。
// ↓↓↓ 再降到300ms复测：log里eRPM打钳位的次数没有明显减少，但实测手感
// 冲击确实比上一版更轻——说明"log里eRPM尖峰次数/是否顶到钳位"这个指标
// 跟真实机械冲击强度没有强对应关系(挣脱够快、单个霍尔扇区内的瞬时测速
// 大概率都会顶到钳位附近，不管挣脱这一下实际力度多大)，转矩·时间才是
// 真正决定手感的量，且它确实在随这两轮调整下降。之后判断这条路线有没有
// 效，以实测手感反馈为准，不再单看log里钳位次数。
// ↓↓↓ 再降到150ms复测：这次是真的过头了——电机在阶跃到-1500后直接卡死，
// 之后整段log(远超一次卡滞重试周期的时长)h/th/base 原地不动，没有再挣脱
// 过，退化成上面说的"卡死到需要手动辅助"。说明150ms已经短到攒不够顶开
// 静摩擦所需的转矩·时间，300ms是当前0.6A这个电流水平下能可靠挣脱的下限，
// 不能再往下压时长；如果还要继续降冲击，得换个量(比如IQ)，不能再压MAX_MS。
// ↓↓↓ 方案A重做触发逻辑：之前是"瞬时转速持续够低"驱动固定"顶MAX_MS/
// 歇REST_MS"循环，不管转子是不是已经追上都顶满一整轮，冲击下限被这个
// 固定顶满的时长卡住。改成"过零低速窗口内+ err(目标-实测)持续跟不上"
// 两个条件同时成立才触发(转子顺畅穿越零点时err本来就小，根本不会触发，
// 天然避免多余推力)；进入用ARM_MS去抖，助推中err一回落到EXIT阈值以下
// 就立刻退出(不用等满一轮)，退出后重新计时形成天然冷却，不再需要单独
// 的"歇"状态。进入/退出用不同阈值(ENTER>EXIT)形成滞回，防止在阈值附近
// 来回抖动。dIq/dt限幅已经在下面斜坡应用那块用FOC_IQ_RAMP_A_PER_S_SLOW
// 实现了，这里不用重复加。
// ↓↓↓ 上机复测确认：过零/反转时基本感觉不到冲击了，可以接受——"机械
// 冲击绝对不可接受"这条这一版达标，参数先冻结在这里。方案B(S曲线参考
// 斜坡)按原计划是"冲击不够收敛才叠加"，既然已经达标就不必须做，后续
// 如果还想进一步压榨/换其他工况复测发现不够用，再回来叠加。
// ↓↓↓ 重开位置环复测，加了诊断计数(hall_edge_win_cnt等，见对应定义处)
// 定位pos几千度跳变的根子，结果排除了"霍尔信号/方向判断错了"——每次
// 跳变的边沿数×实测扇区宽度都跟pos变化量对得上，方向翻转次数也很低，
// 说明是转子真的在那几百ms里快速转了那么多，不是测量或累加的bug。
// 根子在触发条件本身：条件A(|err|>ENTER=500)是照±1500阶跃场景调的，
// 位置环P控制器(Kp=0.3)算出来的目标转速可能只有几百甚至更小，err长期
// 卡在ENTER以下，卡住了却永远摸不到助推，只能拿0.4A这个危险区上限死顶——
// 顶不动不会退化成放弃，而是继续用低转矩、长时间地顶(没有MAX_MS硬上限
// 兜底，因为压根没进入"助推"状态)，攒的转矩·时间可能比方案A本来要压低
// 的还多，一旦某个瞬间(哪怕只是齿槽转矩的微小扰动)真的松动，就是这几千
// 度的野蛮挣脱。加一条纯转速判据(条件B：|eRPM|<KICK_ERPM，不看err，跟
// 方案A之前那版一样)作为条件A的补充，两者任一满足都能触发助推，这样
// 位置环这种"目标转速本来就不大"的场景也能被MAX_MS/ARM_MS这套已经调过、
// 验证过手感的框架接住，不会被晾在旁边无限顶。退出判据也同步简化成
// "eRPM已经不在KICK_ERPM以内(真的动起来了)或到MAX_MS"，不再用err回落，
// 因为条件B触发时err本来就可能已经很小，用err退出会导致助推一进入就
// 立刻被判定"已追上"退出，形同虚设。 */
#define FOC_STALL_KICK_IQ        0.6f    // 助推期间的转矩上限(A)
#define FOC_STALL_ZONE_ERPM      300.0f  // |eRPM|低于此值才算"过零低速窗口"，助推只在窗口内评估
#define FOC_STALL_KICK_ERPM      30.0f   // |eRPM|低于此值才算"真的没转起来"：条件B的入口，也是统一退出判据
#define FOC_STALL_ERR_ENTER_ERPM 500.0f  // 窗口内|err|超过这个值才算"明显跟不上"：条件A，阶跃场景用
#define FOC_STALL_ARM_MS         700U    // 条件A或B任一持续满足这么久才真正触发(去抖)；退出后清零重新计时，天然当冷却
#define FOC_STALL_KICK_MAX_MS    300U    // 单轮助推硬上限，不管有没有追上，到点强制退出
// ↓↓↓ 用户主导设计：碎步压制/脱困软上限/单向续航三层全关掉复测，台阶
// 依旧存在，说明根子不在这几层"事后收尾"机制，往前挖到卡滞助推状态机
// 本身——(a)进入判据只看erpm_now这个瞬时/滤波量，可能被量化噪声/插值
// 误差误判成"卡死"；(b)退出判据是erpm_now单次越过kick_erpm就立刻放行，
// 可能只是一次孤立的、马上又停下来的抖动；(c)卡滞期间err持续存在，
// 速度环积分一直在正常累加、没有被冻结，一旦挣脱，这份历史积分会跟
// 挣脱瞬间的Kp*err一起释放，容易"猛地前窜"。三点分别对应下面三个新
// 参数，详细设计见motion_guard.h顶部第9点说明。都是起点值，待实测调整。
#define FOC_STALL_ENTRY_EDGE_MAX        2U      // 进入去抖(arm_ms)窗口期间，边沿增量超过这个数就不判定为卡死
#define FOC_STALL_EXIT_EDGE_COUNT       5U      // erpm_now越过kick_erpm后还需要再观测到这么多个边沿才真正确认挣脱(4~6)
#define FOC_POST_STALL_INTEG_FREEZE_MS  350U    // 确认挣脱后继续冻结速度环积分这么久(300~400ms)
// ↓↓↓ 用户主导设计："起始位置到目标位置被拆成好几步"——根子是卡滞助推/
// giveup的退出判据(erpm_now刚越过kick_erpm=30)命中那一刻，转子才刚开始
// 从静止加速、动能还很少，iq_cap却立刻从kick_iq/giveup_iq跌回危险区
// settle值，如果这时候齿槽转矩仍然大于settle值能提供的推力，转子会
// 立刻再次停住——每个台阶之间都是一次完整的"卡住->700ms去抖->kick/
// giveup->刚越过阈值又跌回->再次卡住"循环，不是一次连贯的加速-匀速-
// 减速。加一段退出过渡期，撑住比settle更高的力度一小段时间。
// 【第一版，已撤回】直接抬高对称的iq_cap：上机验证暴露回归——iq_target
// 的正负钳位共用同一个iq_cap，抬高后连带放宽了反向修正的转矩权限，转子
// 冲过头时"往回拉"变得比之前更猛(表现为"步伐中间往回迈步")，正向推力
// 窗口变长也让冲过FOC_POS_TRAVEL_LIMIT_DEG前能积累的动能变多(截停距离
// 变大)。且"依旧是台阶"说明连最初想解决的问题都没解决，只带来两个新的
// 负面效果。
// 【第二版，当前生效】改成main.c里跟frag_step/breakout_suppress同一套
// 单向阻断/放宽模式(main.c iq_target最终确定处)：只在iq_target的符号
// 跟这次挣脱方向(motion_guard.c记录的kick_exit_hold_dir)相同时才抬高
// 这一侧的下限，反方向(往回修正)完全不碰，从根上避免连累反向权限。这段
// 过渡期依然不跟挣脱冲击限速屏障(FOC_BARRIER_*，退出这一刻会同时撑起
// 0.3A/800ms的屏障，且屏障clamp最后生效、只收不放)抢档期——屏障是专门
// 为了防冲击验证过的，不动它；过渡期接在屏障hold_ms结束之后才开始算。
// ↓↓↓ 用户要求暂时关掉("把多余的暂时注释掉，让它平滑旋转")：0ms时
// kick_exit_hold_until_ms正好等于屏障到期时刻，"now<until"从到期那一刻
// 起恒为假，等价于完全禁用，不需要改main.c/motion_guard.c的逻辑结构，
// 想恢复时改回一个非0值即可。见FOC_FRAGSTEP_DISABLE_DIAG/
// FOC_BREAKOUT_DISABLE_DIAG声明处的说明，三者是同一轮临时关闭。
#define FOC_KICK_EXIT_HOLD_MS    0U      // 暂时禁用，见上面说明
#define FOC_KICK_EXIT_HOLD_IQ    0.5f    // hold_ms=0时这个值不会被用到
// 位置环重新设计·步骤1：上面这套只管"这一下该不该顶"，不管"已经顶了
// 多久"——位置环场景下转子可能卡住好几秒到十几秒(不像±1500阶跃那样
// err巨大、很快就能重新抓住方向)，期间反复顶(FOC_STALL_KICK_IQ)/歇
// (低于FOC_STALL_KICK_ERPM时退回危险区0.4A)累积的总转矩·时间会远超过
// ±1500阶跃场景验证过的量级，一旦真的松动，释放的能量也就更大——这是
// 位置环两次野蛮挣脱(尤其是edges=144那次)比阶跃场景更猛的直接原因。
// 加一个"本次卡滞发作从什么时候开始"的计时器，卡的时间越长，允许的
// 助推力度越收紧，而不是无限期地按同一幅度反复顶：超过DEESCALATE_MS
// 先把助推电流减半，超过更长的GIVEUP_MS彻底放弃助推(只保留危险区
// 0.4A底线)，接受"这个位置暂时到不了、需要外部条件变化"，不再继续
// 加码尝试。这个改动叠加在条件A/B之上，不改变"要不要触发"这个判据，
// 只影响触发之后能给多大力；±1500阶跃场景的卡滞通常在摸到这两个阈值
// 之前就已经因为err巨大被条件A迅速带走，预期这里基本不会被触发。
#define FOC_STUCK_DEESCALATE_MS  2000U   // 本次卡滞发作累计超过这么久，助推电流减半
#define FOC_STUCK_GIVEUP_MS      5000U   // 累计超过这么久，彻底放弃周期性助推
// 放弃助推后，本次卡滞发作期间(直到真的转起来清零)维持的底线转矩，取代
// 危险区settle_iq_cap那档(0.4A)。物理测试确认卡死时手感"没什么阻力，只有
// 微弱磁力顶/轻微跳动感，但不转"，排除了摩擦/负载，指向电机自身齿槽转矩
// (cogging torque, 跟外部负载无关)——0.4A可能不足以持续压过局部齿槽detent。
// 取在0.4A(危险区底线)和0.6A(FOC_STALL_KICK_IQ助推电流)之间，先从偏保守的
// 一档开始，按"改一处->复测->再改下一处"节奏调。
#define FOC_STUCK_GIVEUP_IQ      0.5f
// ↓↓↓ 用户诊断：z→500实测出现单窗口edges=67(约4020°)的巨大挣脱，挣脱前
// giveup_iq已经在原地顶满0.5A维持了很久——不要等到giveup满额顶死才冲破
// 阻力，那一下的初始加速度/动能天然就大。新增"giveup斜率自适应衰减"：
// 卡滞持续时长越过giveup_ms门槛后，先按满额giveup_iq维持一个DECAY_STEP_MS
// 周期(呼应"短时助推克服轻微卡滞")，仍未起步就每过一个DECAY_STEP_MS
// 阶梯下调DECAY_STEP_IQ，直到IQ_FLOOR封底(封底必须仍然明显高于危险区
// FOC_SPEED_IQ_MAX(0.4A)，否则退化回"齿槽压不过去、永远到不了目标"那个
// 已修复的旧问题)——用越来越小的静态转矩去试探能不能压过齿槽，一旦真的
// 松动，起步瞬间可用的动能上限也跟着变小。都是起点值，待实测调整。
#define FOC_STUCK_GIVEUP_DECAY_STEP_MS  1000U  // 每隔这么久(卡滞超过giveup_ms之后)下调一档
#define FOC_STUCK_GIVEUP_DECAY_STEP_IQ  0.02f  // 每档下调多少安培
// ↓↓↓ 上机验证暴露回归：封底0.42A太接近危险区0.4A，多次实测"手感一直
// 没有冲击感，但也一直收敛不到位"——卡在远离目标的位置后，giveup_iq
// 衰减到封底附近就再也压不过齿槽转矩了，长期edges=0原地打转。0.5A是
// 这个session更早专门验证过"能可靠压过去"的经验值，封底定得太低等于
// 牺牲了这份可靠性去换挣脱能量降低，但降太多直接变成"压根挣脱不了"，
// 不是"挣脱得更轻"。调高封底到0.46A，把衰减的绝对幅度收窄(0.5→0.46，
// 只留4档)，仍然保留"卡越久力度越收紧"这个方向，但不再逼近已知不可靠
// 的量级。
#define FOC_STUCK_GIVEUP_IQ_FLOOR       0.46f  // 衰减下限(A)，从0.42上调，避免逼近危险区导致挣脱不出来
// 双向转矩([-IQ_MAX, +IQ_MAX])：位置环需要能在冲过目标位置时主动拉回来，
// 只给正转矩、靠摩擦停是不够的。

// 排查"到位后还会自己动"用：关掉整个卡滞助推+giveup后现象依旧(只剩
// creep自转机制能解释，已经在FOC_HALL_TIMEOUT_CREEP_HZ那边加了arrived
// 抑制)，排除了卡滞助推本身的嫌疑，改回0恢复正常功能，用真实配置验证
// creep抑制这个修复。
#define FOC_STALL_KICK_DISABLE_DIAG 0

// 用户要求："把多余的暂时注释掉，让它平滑旋转"——把这几轮陆续加上去、
// 专门为"让挣脱/收敛更漂亮"服务的几层附加机制临时关掉，只保留最核心的
// 一套：轨迹发生器+速度/电流环PI+卡滞助推/giveup(没有这两个，转子撞上
// 真实齿槽卡点可能永远动不了，不是"多余"，是能不能走完全程的前提)+
// 挣脱冲击观测限速屏障(核心防冲击机制，"机械冲击绝对不可接受"这条线
// 靠的就是它，不能关)+行程软限位(硬安全边界，同样不能关)。关掉之后
// 如果转子本身能顺着轨迹相对平滑地跑完全程，说明这几层附加机制才是
// "台阶"/"往回迈步"的成因；如果关掉之后卡住不动或者依然不平滑，说明
// 问题在更底层(比如轨迹本身的加减速度、危险区0.4A基线转矩)，不在这几
// 层。三个开关都置1为禁用，置0恢复；不改变任何底层数值，只是暂时不让
// 这几段代码生效，方便随时切回来对比。
#define FOC_FRAGSTEP_DISABLE_DIAG     1   // 置1：碎步压制(frag_step)不再触发
#define FOC_BREAKOUT_DISABLE_DIAG     1   // 置1：脱困速度软上限(breakout_suppress)不再触发

// 用户主导设计："先通过固定积分限幅来判断能越过齿槽、同时又不产生台阶的
// 电流为多少，之后再采用分区自适应积分限幅，要关闭掉其他干扰项"——在
// 排查清楚"饱和积分"不是台阶/超限位的主因(speed_integ冻结期间不累加、
// 且每拍都被±iq_cap硬钳，没有真正意义上的windup)之后，用户提出更直接
// 的思路：与其继续在"卡滞助推kick_iq/其距离收紧/giveup_iq及其时长-距离
// 衰减"这一整套状态触发式跳变逻辑里找参数，不如先做一次纯净实验——未
// 到位期间全程用同一个常数电流上限(不再有任何跳变)，把这个数从低往高
// 扫，找到"刚好能持续压过齿槽、不会卡死，同时又不会因为电流本身/状态
// 跳变而产生台阶"这一个临界值，摸清楚这个数之后，再去设计真正的"分区
// 自适应限幅"(按剩余距离分区取不同基准，而不是继续用现在这套跳变模式)。
// FOC_FIXED_CAP_TEST_DIAG=1时，"未到位"期间(!pos_arrived)iq_cap被强制
// 覆盖成FOC_FIXED_CAP_TEST_A这一个常数，覆盖掉：settle基线(FOC_POS_
// TRANSIT_IQ_MAX)、stall_kicking的kick_iq/半档及其距离收紧(dist_cap)、
// giveup_iq及其时长/距离双重衰减——这些跳变来源在测试期间全部失效，
// 只剩这一个常数在起作用。frag_step/breakout_suppress已经是关的(见上面
// 两个DISABLE_DIAG)，kick_exit_hold也是关的(HOLD_MS=0)，不用再管。
// ↓↓↓ 唯一不覆盖的例外：挣脱冲击限速屏障(barrier_active)。这是"机械
// 冲击绝对不可接受"这条线真正的安全网(挣脱瞬间按观测到的转速幅度临时
// 收紧iq_cap到0.3A/800ms)，跟"多大电流能越过齿槽"这个问题是两回事——
// 测试期间如果把它也覆盖掉，等于在扫电流的同时关掉了防冲击保护，一旦
// 扫到的值偏大就有真实冲击风险。所以覆盖判据额外加了!barrier_active，
// 屏障生效期间让它按自己算出来的更低值走，覆盖只在屏障没有生效的其余
// 时间起作用。行程软限位(FOC_POS_TRAVEL_LIMIT_DEG)同样完全不受这个
// 开关影响，照常在最后一道生效。
// FOC_FIXED_CAP_TEST_A是待扫描的值，每次改这一个数重新编译测试，按
// "改一处->复测->再改下一处"的节奏从低往高试；已知参考点：0.4A(危险区
// 基线)不够稳定越过齿槽，0.5A(giveup_iq)是这个session更早验证过的"能
// 可靠压过去"经验值，0.6A(kick_iq)是±1500阶跃场景验证过手感能接受的
// 上限，起点先取两者中间偏保守的0.45A。测出临界值后把DIAG改回0，把
// 结论交给下一步的分区自适应限幅设计用。
// 【第一版，已撤回】直接覆盖对称的iq_cap：上机验证暴露回归——iq_target
// 的正负钳位共用同一个iq_cap，覆盖后连带放宽了反向修正的转矩权限，跟
// 这个session更早"抬高FOC_POS_TRANSIT_IQ_MAX/kick_exit_hold第一版"两次
// 独立验证过的"对称iq_cap陷阱"是同一个机制。第一次上机表现为"持续反转、
// 越来越远离目标"(关掉行程软限位后没有任何东西兜底，反向的这份多余
// 权限被放到最大)，重新上电后表现为"中途反复反向"(同一个机制，严重
// 程度不同，取决于当时err/erpm的具体状态)。
// 【第二版，当前生效】改成main.c iq_target最终确定处，跟kick_exit_hold
// 同一套"只在跟当前轨迹方向(traj_dir)相同的一侧封顶，反方向完全不碰"
// 的模式，见该处的详细说明。
// ↓↓↓ 用户主导决策：0.7A实测依旧摆动+台阶未消失，判断问题大概率不在
// 电流大小(卡滞检测状态机本身的结构性问题)，转去做蠕行模式实验(见
// FOC_POS_CREEP_*说明)，这个开关先关掉，避免两个实验同时生效互相干扰。
#define FOC_FIXED_CAP_TEST_DIAG   0        // 置1启用固定限幅测试，置0恢复正常的状态触发式iq_cap
#define FOC_FIXED_CAP_TEST_A      0.5f     // 待扫描的固定电流值(A)，0.45A已测：不再反向，但依旧台阶，
                                            // 往上试这个session更早验证过的"能可靠压过去"经验值0.5A

// ---- 阶跃响应测试 ----
// 纯速度环+1500->-1500瞬间反转阶跃实测会在过零附近反复卡住/回弹——零速
// 附近霍尔跳变本来就稀疏，角度插值全靠外推，电流环+粗霍尔量化互相打架。
// 修复方向：给speed_ref本身加斜坡(下面FOC_SPEED_REF_RAMP_ERPM_S)，让指令
// 平滑地从+1500滑到-1500，而不是指望电机自己消化一个瞬间反转指令。
// 原来只测一次1500->-1500就完事，之后一直停在-1500不动——只覆盖了单次
// 反转响应，没覆盖"反复正反转"这种更接近实际使用的场景。改成往复循环：
// 每个目标保持HOLD_MS后翻转到另一个，一直循环下去，不用重新烧录/复位
// 就能测很多次反转，也更容易在log里观察到偶发的、多次尝试才复现一次的
// 问题。
#define FOC_SPEED_STEP_TEST      1
#define FOC_SPEED_STEP_LOW_ERPM  1500.0f          // 目标A：正转(沿用验证过的值)
#define FOC_SPEED_STEP_HIGH_ERPM -1500.0f         // 目标B：反转，同样的转速量级
#define FOC_SPEED_STEP_HOLD_MS   5000U            // 每个目标保持这么久，之后翻转到另一个
#define FOC_SPEED_REF_RAMP_ERPM_S 1000.0f         // speed_ref斜坡速率(eRPM/s)
// 分段斜坡：低速穿越区(齿槽纹波明显、霍尔跳变稀疏)跟远离零速的正常区，
// 需要的斜率天生不一样，同一个斜率会拿"正常区才够用"的速度硬闯纹波。
// 滞回带(LOW_ZONE_HYST)用进入/离开两个不同门限(Schmitt触发器思路)，
// 避免判定在阈值边界上抖动。这两个值都是起点，可按实测log继续调整。
#define FOC_SPEED_REF_RAMP_LOW_ERPM_S   150.0f   // 低速区斜率(eRPM/s)，待调
#define FOC_SPEED_REF_LOW_ZONE_ERPM     400.0f   // |speed_ref|低于此值 -> 进入低速区
#define FOC_SPEED_REF_LOW_ZONE_HYST     100.0f   // 要回升超过(阈值+滞回)才判定离开低速区

// ===== 位置环 =====
// 位置误差(目标-实际机械角度) -> P控制器 -> 输出转速给定，喂给上面的速度环
// (级联结构：位置环->速度参考->速度环->Iq_ref->电流环)。反馈来自
// rotor_pos_rad_e(FOC_HallEdge里带符号累加的电角度)，除以极对数换算成
// 机械角度——分辨率就是霍尔的60°量级，做不到编码器那种精细定位。
// 第一次重新打开就复现了更根本的问题，关掉过：pos反馈(rotor_pos_rad_e)
// 在近零速卡滞-混乱挣脱那段出现过几千度/330ms的跳变。方案A(见上面
// FOC_STALL_*说明)把挣脱这一下的物理冲击压到手感基本感觉不到了，
// 但重新打开复测发现同样的pos跳变原样复现(837.7→-4561.8、
// -4384.8→2338.6→3716.6、3001.4→-1024.9，都是几千度量级)——说明方案A
// 解决的是"挣脱这一下多猛"(转矩·时间/物理冲击)，跟"位置估计为什么会
// 飞出去"是两个不同的根子，压根没碰到后者；而且比冲击更危险，因为
// rotor_pos_rad_e一旦读出离谱假值，位置环P控制器会拿着一个跟实际完全
// 对不上的误差去算目标转速，可能把电机往错误方向/错误力度驱动。此外
// 还发现方案A的FOC_STALL_ERR_ENTER_ERPM=500是照±1500阶跃场景调的，
// 位置环P控制器算出来的目标转速可能远小于1500(比如只有几百)，err卡在
// ENTER阈值以下时同样"卡住不动"却不会触发助推，这个缺口也没堵上。两个
// 问题都没解决前不能开，先关掉。真正要修的是rotor_pos_rad_e本身没有
// 类似FOC_HALL_OMEGA_CLAMP_ERPM那样的累加保护，得先查清楚这几千度的
// 跳变是转子真的飞转、还是方向判断被带偏累加出的假位置，再考虑重开。
// ↓↓↓ 加了诊断计数(hall_edge_win_cnt/hall_dirflip_win_cnt/hall_dt_min_win，
// 见对应定义处说明)复测，结果排除了"霍尔信号/方向判断错了"：每次跳变
// 的edges×实测扇区宽度都跟pos变化量对得上(比如edges=78时delta≈78×60°，
// 边沿数直接解释了跳变量)，flip也很低，说明转子是真的在那几百ms里
// 快速转了那么多，不是测量或累加的bug。根子在FOC_STALL_ERR_ENTER_ERPM
// 这条触发判据本身——已经在上面FOC_STALL_KICK_ERPM说明里加了条件B补上
// 这个缺口(位置环这种目标转速本身不大的场景现在也能摸到助推、不会被
// 晾在旁边无限期低转矩硬顶)。但这个改动同时影响阶跃测试那条已经验证
// 过手感的路径，必须先在±1500阶跃场景上复测确认没有退步，再回来重开
// 位置环验证，不能想当然连着两处一起测。
// ↓↓↓ ±1500阶跃复测确认手感没有退步(还是基本感觉不到冲击)，条件B
// 加入没有影响已验证的路径。重新打开验证条件B有没有堵上位置环这边的
// 缺口，结果：条件B确认有生效(长时间卡滞期间能看到Iq在0.4~0.53之间
// 周期性波动，不再是死钉在0.400不动那种)，但没能防住最坏情况——出现
// 了一次比之前任何一次都更猛的挣脱(edges=144 flip=0，pos跳变≈+8639°，
// 144×60°完全对得上，依然是转子真实高速旋转，不是测量误判，换算下来
// 瞬时转速轻松超过4000eRPM)。说明条件B解决的只是"该不该触发助推"这个
// 判据缺口，没解决更根本的问题：位置环这套纯P控制器+级联速度环，长时间
// 卡滞后会攒出巨大位置误差，一旦挣脱，P控制器算出来的目标转速本身就
// 顶到FOC_POS_SPD_MAX_ERPM=2000上限，驱动出来就是失控式猛冲——已经不是
// "卡滞挣脱那一下的转矩·时间"能解释的量级，继续在FOC_STALL_*上打补丁
// 解决不了，需要更根本的重新设计(比如给位置环输出的目标转速本身加斜率
// 限制、或者从纯P换成带阻尼的结构)，不是能顺手改完的量级，先关掉。
// ↓↓↓ 位置环重新设计·步骤1(卡滞发作总时长限幅，见上面FOC_STUCK_*说明)
// 落地，且已经过一轮独立的死区bug修复(FOC_HALL_TIMEOUT_CREEP_HZ，见其
// 说明——之前两次"停转"是它导致的，不是位置环本身的问题)。±1500阶跃
// 场景回归确认没有退步，重新打开验证步骤1有没有把edges=144那次的野蛮
// 挣脱压下去。 */
#define FOC_POSITION_LOOP        1
#define FOC_POS_REF_DEG          180.0f    // 历史遗留：指令接口上线后不再驱动实际目标，仅作参考
#define FOC_POS_HOLD_MS          3000U     // 历史遗留：同上，不再使用
// ↓↓↓ 步骤1复测结果：最终能收敛到目标附近停住(不再是原来那种无限期
// 越冲越猛)，过程中最猛的一次跳变edges=57(≈3400°)，比步骤1之前的
// edges=144明显收窄(降了约60%)，说明卡滞发作总时长限幅确实在压peak
// severity，方向对，但57个边沿依然是一次挺大的真实高速旋转，"机械冲击
// 绝对不可接受"这条线大概率还没达标。按计划叠加步骤2。
// 步骤2：把纯P控制器换成距离感知的减速轮廓(trapezoidal思路)——原来
// speed_ref_target=Kp*err会让目标转速在卡滞期间随err线性增长、很快
// 顶到SPD_MAX_ERPM封顶，一旦挣脱就是朝着"全速冲刺"的指令去的，没有
// 随距离接近提前减速的机制，容易冲过头、在目标另一侧又攒出大误差，
// 这是步骤1之前那种交替符号连续大跳变(-4183→-5189→-3811→+4827…)的
// 动力学根源。新公式v_max=sqrt(2·减速度·剩余距离)：允许的最大速度
// 随剩余距离的平方根自然收窄，越接近目标允许的速度越低，从源头抑制
// "一路顶着限幅冲到跟前才反应"这种振荡放大。P控制器没有积分项，位置
// 环分辨率天然被霍尔60°粗量化限制，稳态本来就会有残留误差(正常现象)。
// ↓↓↓ 600这个起点值实测证伪："转到目标位置"测试里转子在目标两侧来回
// 冲(3583→-1876→2029，目标1080)，不是单向到达即停，而是"两边夹逼"式
// 振荡收敛——用户明确指出这不符合位置环控制的预期(该单向移动、到位后
// 主动停止)。根因：v_max=sqrt(2·600·剩余距离)这个公式承诺了"按600eRPM/s
// 能刹得住"，但挣脱之后真正能用的刹车转矩上限只有危险区FOC_SPEED_IQ_MAX
// =0.4A——这600的减速度从来没有验证过0.4A能不能真正做到，公式在"画饼"。
// 一旦挣脱成功、转子被顶向v_max算出的目标速度，接近目标时目标速度按
// 平方根快速收窄，但0.4A刹不住已经积累的动能，冲过目标，到另一侧误差
// 反号再来一轮同样的过程。不能靠"挣脱后专门放开刹车权限"来治——类似
// 思路(减速方向豁免)已经证伪过，游荡范围从9700°恶化到25994°/35593°，
// 还出过Id=5.37A的D/Q解耦异常。这次反过来：不加大刹车，从源头把允许
// 建立的动能压下去，让0.4A的刹车能力配得上这个减速轮廓的承诺。降到
// 150(约1/4)：跟本session之前观测到的"高速巡航段"实测衰减速率(约
// 300~400eRPM/s量级，且那段还不是全程满0.4A)比，留了2倍以上余量，
// 仍是经验起点值，待实测再调。
#define FOC_POS_DECEL_ERPM_S     150.0f   // 减速轮廓允许的最大"减速度"(eRPM/s)，需要与危险区0.4A实际刹车能力
                                            // 匹配，不能只是好看的公式，见上面说明
#define FOC_POS_SPD_MAX_ERPM     2000.0f   // 位置环输出的转速给定限幅(减速轮廓算出的v_max还要再过这道封顶)

// 卡滞助推挣脱转矩按剩余距离收紧：kick_iq(0.6A)是固定值，跟FOC_POS_DECEL_
// ERPM_S调低是同一个"少建立动能"思路的另一半——离目标越近，能容许挣脱
// 时建立的动能应该越小，否则固定的大挣脱力一冲还是容易过头。下限钳在
// giveup_iq：giveup这条底线本身是专门用来压过齿槽转矩定的，卡滞助推的
// 收紧不能钻到比它还低，否则重新制造"转不到目标位置"那个已经修复过的
// 问题(见FOC_STUCK_GIVEUP_IQ说明)。这段只处理stall_kicking自己的iq_cap，
// giveup那边的远近分区是另一套独立机制，见下面FOC_POS_GIVEUP_SCALE_
// DIST_DEG说明(通过MotionGuard_Update的giveup_dist_scale参数生效，
// 不是这里的dist_cap后处理)。
#define FOC_POS_KICK_SCALE_DIST_DEG  360.0f   // 剩余距离(度)大于此值给满额kick_iq，更近按比例收紧，起点值待实测调整

// ↓↓↓ 用户主导设计：废除"giveup恒定用固定基准giveup_iq、不看剩余距离"
// 这个隔离——实测证实这个隔离导致"不管离目标多近，giveup挣脱的位移量级
// 都一样"，多轮挣脱后"收敛"只是恰好落进容差，不是真正意义上的逼近(比如
// 1631.4°→308.4°→-590.1°绕了一大圈才恰好落进473°)。giveup_dist_scale=
// 剩余距离/FOC_POS_GIVEUP_SCALE_DIST_DEG，钳到[0,1]，喂给MotionGuard_
// Update，由它按这个比例在giveup_iq(远，=1.0时)和giveup_iq_floor(近，
// =0.0时)之间取基准，再叠加原有的卡滞时长阶梯衰减。阈值定得比kick用的
// 360°更大(720°)：giveup本身是压齿槽的最后一道底线，不宜像stall_kicking
// 那样早早收紧，起点值待实测调整。
#define FOC_POS_GIVEUP_SCALE_DIST_DEG  720.0f

// 碎步运动识别->短时主动压制助推(用户主导设计)：giveup斜率衰减解决了
// "顶满giveup_iq蓄力太久"这个问题，但实测复现了新的模式——挣脱后不是
// 一次冲到底，而是一连串单边沿(约60°)小跳(edges=1~2/周期)首尾相接，
// 每一小跳erpm都不低(600~2000+)，说明电流环仍在持续给力，只是碰巧每
// 一下只够跨过一个扇区就被下一次判定打断重新加速——连续短跳接力比
// giveup_iq固定顶满更隐蔽，因为每一下单看都不大，但累积起来总冲出距离
// 依然可观(实测约1055°)。识别依据：短时间窗口内edges数落在"不是完全
// 卡死(0)、也不是已经真正连续跑起来(很多)"这个中间地带，就是这种碎步
// 接力的特征——检测到就主动把iq上限压得比giveup_iq_floor更低，并且
// 禁止foc_iq_ref在同一方向继续叠加(只许维持或反向/回落)，打断"这一跳
// 还没完全刹住，下一跳的加速就已经叠上来"这条链条。跟giveup衰减是同一条
// 因果链上不同的治理点：衰减管"起步前蓄了多大力"，这个管"起步后还要不要
// 继续叠加力"。都是起点值，待实测调整。
#define FOC_FRAGSTEP_WINDOW_MS    150U    // 每隔这么久检查一次窗口内edges数
#define FOC_FRAGSTEP_MIN_EDGES    1U      // 窗口内edges数落在[MIN,MAX]区间才判定为"碎步接力"
#define FOC_FRAGSTEP_MAX_EDGES    3U      // 超过这个数视为"已经真正连续跑起来"，不再压制
#define FOC_FRAGSTEP_HOLD_MS      300U    // 判定命中后压制状态维持多久(不够下一个窗口就先关掉)
#define FOC_FRAGSTEP_IQ_CAP       0.35f   // 压制期间的Iq上限(A)，明显低于giveup_iq_floor

// ↓↓↓ 用户主导设计："到达475之后应该停止，却继续爬升到1626.7才停"这类
// 大超调坐实：giveup/kick挣脱瞬间释放的转矩，会把低惯量转子加速到远超
// 轨迹本身需要的速度(实测冲到1400~2000eRPM，轨迹巡航目标常常只有一两
// 百eRPM)，多出来的动能只能靠已经压死在0.4A的刹车(FOC_POS_DECEL_ERPM_S
// =150eRPM/s这个减速度就是照着0.4A刹车能力标定的)慢慢消化，逼出上千度
// 的超调。不能再往"放宽刹车方向上限"这条已经证伪的路上走(那次pos游荡
// 范围从约9700°恶化到25994°/35593°，还出现过Id=5.37A的D/Q解耦异常)，
// 所以改在起步端限速：用轨迹自己这一刻的期望速度speed_ref_target划一条
// 软上限v_limit=|speed_ref_target|+FOC_BREAKOUT_SPD_MARGIN_ERPM，giveup
// 还在生效期间、或stall_kicking刚退出的FOC_BREAKOUT_SPD_HOLD_MS窗口内
// (覆盖foc_iq_ref斜坡还没跟着降下来、惯量还在延续的这段)，一旦实测转速
// 持续超过这条软上限，就跟碎步压制共用同一段"同方向不许继续叠加"的
// 阻断逻辑——只压制"继续加速"，不主动加大刹车力度，风险模型跟"减速方向
// 豁免"完全不同。都是起点值，待实测调整。
#define FOC_BREAKOUT_SPD_MARGIN_ERPM   50.0f   // v_limit = |speed_ref_target| + 此值(eRPM)
#define FOC_BREAKOUT_SPD_HOLD_MS       500U    // stall_kicking退出后维持监视这么久，覆盖惯量延续窗口

// ↓↓↓ 用户主导设计(方案A)：第一版上机验证暴露问题——"不许同方向继续
// 叠加"这个被动阻断，命中时iq_target往往已经因为err很负而自然小于
// foc_iq_ref(PI自己在降，只是卡在积分解卷绕，降得慢)，阻断条件
// (iq_target>foc_iq_ref)压根没被触发，形同空转；转子在PI慢慢解卷绕的
// 这几秒里持续被尚未降下来的正向转矩推着，超调量级跟没加这层保护之前
// 基本没变。用户诊断：保护层需要从"被动等PI"升级成"主动压转矩"，
// 优先级高于速度PI，强制foc_iq_ref下行，不再等积分自己解卷绕；
// 且要按固定速率(禁止阶跃)+滞回(避免贴边界抖动切换)。
// 触发窗口在原设计基础上并入frag_step_active：实测第一个edge(比如
// eRPM=2230那一下)出现时，frag_step的[1,3]edges窗口往往会先命中(碎步
// 判定的初衷是抓"小跳"，但挣脱最初一瞬间还没来得及产生第4个edge，也
// 会先落进这个区间)，比giveup/barrier/kick退出窗口更早看到征兆，能把
// 主动压制的介入时机提前。
#define FOC_BREAKOUT_PULLDOWN_A_PER_S  3.0f    // 主动下压天花板的下降速率(A/s)，跟giveup那档"比正常快但
                                                // 仍按固定速率、不阶跃"的量级看齐
#define FOC_BREAKOUT_HYST_ERPM         30.0f   // 滞回：已经在压制中时要回落到v_limit-此值以下才退出，
                                                // 避免贴着v_limit边界反复切换

// ↓↓↓ 曾经试过"卡滞蓄能抑制"(卡滞诊断期间把speed_ref_target幅度压小
// +pos_err解冻一阶低通)，缓解但没有根治"反复挣脱-超调-反向挣脱-再超调"
// 问题——治标不治本：只要目标速度还是"拿瞬时(或冻结/低通)误差反应式地
// 算出来的"，卡住越久这个目标就攒得越久，迟早还是会在挣脱那一刻把攒
// 下的量顶出去，压幅度/低通只是让顶出去的量小一点，没有从根上断掉
// "卡住时间越久->目标积累越多"这条因果链。用户提出更彻底的方案：改用
// 轨迹发生器(见下面FOC_POS_TRAJ_*)——目标速度不再由瞬时误差决定，而是
// 由一条提前规划好、只随"已经过去的时间"展开的位置/速度参考曲线决定，
// 卡住多久跟这条曲线本身的进度无关(曲线该怎么走还怎么走，卡住只是让
// 实际位置暂时落后于曲线，不会让曲线本身停下来等)，"蓄力"这件事在
// 这个架构里根本不存在。上面那版"卡滞蓄能抑制"因此被完全取代，不再
// 使用(motion_guard.c里的pos_err冻结/一阶低通机制仍然保留，只是main.c
// 这边不再调用MotionGuard_GetPosErrForSpeedCalc()消费它)。
//
// ↓↓↓ 上线后暴露新问题：z→500实测第一次真实挣脱edges=1很正常，紧接着
// 下一个打印窗口edges=68(约4080°)一次冲过目标924°，屏障mg=0/1/0确实
// 介入但没能挡住——根因是轨迹曲线原来按"过去了多少墙钟时间"展开，跟
// 转子有没有真的在动无关：这次距离约3101°，三角形轮廓加速段要将近
// 1.9秒才到峰值巡航速度，但转子这段时间一直卡着没动，墙钟时间照样在
// 走，等真正挣脱那一刻，前馈速度早已经爬到接近巡航速度的大值——不是
// "蓄力"复发(蓄力问题已经解决，这次没有随卡滞时长无界增长)，而是
// "卡滞吃掉了轨迹的时间预算，挣脱时前馈本身已经跑远"。用户提出的修复：
// 轨迹的时间基准改用"有效运动计时"(traj_elapsed_s)，只在没有被
// MotionGuard判定为卡滞助推/giveup期间才推进，卡滞期间直接冻结在原地
// (不是按更慢速率走，是完全不走)，挣脱后从冻结点继续——曲线本身该怎么
// 走还怎么走，只是"计时器"不再跟卡滞的墙钟时间绑死，从根上避免"卡多久
// 就在曲线上跑多远"。见下面traj_elapsed_s/traj_last_calc_ms声明处的
// 实现说明。
#define FOC_POS_UNFREEZE_TAU_S       0.3f    // motion_guard.c内部的pos_err解冻一阶低通时间常数(秒)，
                                              // 仍然喂给MotionGuard_Init(保持该模块自身状态完整/可独立
                                              // 复用)，但main.c位置环这边已经不再消费它算出来的结果

// 轨迹发生器：梯形轮廓(恒加速->匀速(若距离够长)->恒减速)，替代旧的
// "v_max=sqrt(2·减速度·剩余距离)"反应式公式。加速度/限速直接复用
// FOC_POS_DECEL_ERPM_S/FOC_POS_SPD_MAX_ERPM这两个本session已经实测调过
// 的量级(1eRPM/s=6°/s²机械角，MOTOR_POLE_PAIRS=1时电角度=机械角)，不
// 重新引入未验证的新数值。见main.c位置环主循环块里的具体用法。
#define FOC_POS_TRAJ_ACCEL_DEG_S2   (FOC_POS_DECEL_ERPM_S * 6.0f / (float)MOTOR_POLE_PAIRS)
#define FOC_POS_TRAJ_VMAX_DEG_S     (FOC_POS_SPD_MAX_ERPM * 6.0f / (float)MOTOR_POLE_PAIRS)
// 轨迹跟踪反馈：前馈(轨迹自身的参考速度)为主，这个增益只做小幅度修正
// (纠正霍尔量化噪声、卡滞期间落后于轨迹的追赶)，不能喧宾夺主变成新的
// "反应式蓄力"入口——真正的挣脱力度还是交给MotionGuard的卡滞助推/
// giveup转矩上限机制，这里的反馈项只管方向对、力度小。都是起点值，
// 待实测调整。
#define FOC_POS_TRAJ_KP_ERPM_PER_DEG  0.5f    // 反馈增益(eRPM/度)
#define FOC_POS_TRAJ_FB_CAP_ERPM      100.0f  // 反馈修正项自身的独立幅度上限

// ===== 蠕行模式(用户主导设计) =====
// 用户观察：开机I-F开环启动那段("找初始位置")比现在这套"轨迹参考+霍尔
// 测速PI+卡滞助推"顺滑得多——本质是磁场按给定时间曲线匀速转、完全不看
// 霍尔反馈做实时决策，没有"卡死判定->去抖->助推"这套状态机反复跳变。
// 用户提出的安全模型：借鉴开环"匀速旋转、避免状态机频繁跳变"的顺滑
// 优点，但保留霍尔反馈做监控——距离目标远时进入蠕行模式，参考角度按
// 固定角速度纯时间推进(不看反馈)，Iq只做简单限幅(不跑完整速度PI，
// 规避PI-stall-giveup来回切换)；霍尔全程持续采样，只做观测比对，不
// 参与蠕行期间的实时角度控制；一旦参考角度与霍尔实测角度的电角度差
// 持续超阈值(判定失步/卡死)，或者已经接近目标，立刻退出蠕行，交还给
// 原有闭环位置环(轨迹发生器+速度环PI+卡滞助推/giveup)收尾——远距离
// 大部分行程顺滑蠕行，失步/临近目标这两种情况仍然有成熟的闭环机制
// 兜底，不会真的"裸奔"开环走完全程。
// 电角度失步阈值：霍尔一个扇区固定是60°电角度(跟极对数无关，极对数
// 只影响一个扇区对应多少机械角)，30°(半扇区)量级的差在正常量化噪声/
// 观测滞后下就可能出现，起点先取1.5个扇区(90°)避免量化噪声本身就把
// 这条线冲穿，需要根据实测调整——过紧会导致蠕行还没怎么走就被误判失步
// 退出，形同虚设；过松会让真失步拖很久才被发现。
// ↓↓↓ 用户主导决策：退出蠕行切回闭环那一刻实测坐实两次真实冲击/剧烈
// 转动——第一次(近目标退出，eRPM瞬间顶到3000/单窗口edges=194/超调约
// 370°)诊断为foc_theta角度来源瞬间切换导致，补了固定severity屏障
// (MotionGuard_ArmBarrierKickExit)想在退出瞬间把转矩权限压低给物理
// settle时间；复测后用户反馈"不行，有剧烈转动"，说明这个修复没有真正
// 压住问题(屏障只压iq_cap这个上限，压不住angle突变本身直接改变的实际
// 输出转矩方向/大小这个更底层的机制——参照之前giveup反向权限/kick_iq
// 提升那些教训：治标的转矩层面补丁压不住结构性问题，需要先撤回换回
// 验证过的路径，不能继续在这个方向上打补丁)。先完全关掉蠕行模式，
// 退回这个session更早验证过安全的纯闭环路径(轨迹发生器+速度环PI+
// 卡滞助推/giveup+行程软限位)，蠕行相关代码全部保留但编译期禁用，
// 后续如果要重新尝试，思路上大概率需要先解决"角度来源切换本身如何
// 平滑过渡"这个更底层的问题，而不是继续在转矩幅度这一层调参数。
// ↓↓↓ 用户主导决策：按上面诊断出的方向补了FOC_POS_CREEP_ANGLE_BLEND_MS
// 角度矢量平滑过渡(见该宏+main.c里ISR角度分支的完整说明)，重新打开
// 蠕行复测。之前实测蠕行本身(顺滑段+不反向+能到达目标)已经确认没问题，
// 只是60°/s"到达目标时间过长"，一并把速度提到150°/s——只改这一个变量，
// 电流(0.7A)不动，如果150°/s下失步(desync)频率明显升高，再回头考虑
// 电流是不是也要跟着提。
// ↓↓↓ 用户主导决策(第N次回退，本轮最终结论)：之后又陆续补了积分冻结
// (蠕行期间speed_integ)、"有效运动计时"冻结(traj_elapsed_s，真正找到
// 的一个根因)、蠕行本身转速上限(FOC_POS_CREEP_SPEED_CAP_ERPM)、超速时
// 硬截断foc_iq_ref(绕过斜坡)——每一处都是真实存在的问题、也都改对了，
// 但"退出蠕行后能不能稳稳收敛到目标"这个根本诉求反复上机验证始终没能
// 达成(还有反弹，转到目标停不下来)。这说明卡住的不是某一个还没堵上的
// 具体漏洞，而是"开环恒定转矩蠕行+移交给刻意温和刹车的闭环"这个组合
// 本身，在纯霍尔60°粗量化反馈(没有编码器)下天生就很难同时做到快、稳、
// 准。蠕行最初是为了解决闭环路径的"台阶"问题，但闭环路径虽然不够顺滑、
// 至少能可靠收敛到位(这个session更早已反复验证)。用户主导决策：先
// 彻底关掉蠕行，退回验证过安全且能可靠到位的纯闭环路径，不再在这套
// "开环蠕行+事后补丁"的机制上继续投入——蠕行相关代码全部保留(角度平滑
// 过渡/转速上限/硬截断这些子机制本身都没错，只是组合起来没能解决根本
// 问题)，后续如果要重新尝试位置环顺滑化，大概率需要换一个方向(比如
// 真正的角度闭环控制，而不是开环蠕行+退出时修补)，不是继续在这套机制
// 上调参数。
#define FOC_POS_CREEP_DIAG            0        // 置1启用蠕行模式，置0完全走原有闭环路径(不影响其它机制)
#define FOC_POS_CREEP_ENTER_DIST_DEG  150.0f   // |pos_err|超过这个值才进入蠕行(只用于远距离趋近)
#define FOC_POS_CREEP_EXIT_DIST_DEG   100.0f   // |pos_err|小于这个值强制退出蠕行，切回闭环做精确定位
                                                // (比ENTER小，留出滞回区间，避免边界反复进出)
#define FOC_POS_CREEP_SPEED_DEG_S     150.0f   // 蠕行阶段的恒定机械角速度(°/s)，比轨迹发生器巡航速度
                                                // (FOC_POS_TRAJ_VMAX_DEG_S约461°/s)低得多，图的是稳不是快
// ↓↓↓ 用户主导决策：150°/s实测在起步阶段(还在500ms爬升期内)就触发失步
// 退出(desync=242.5°_e，pos只走了4.5°)——转子起步还在克服齿槽阻力低速
// 爬升，参考角度已经按更快的目标速度冲上去，两者差距很快冲穿失步阈值，
// 蠕行在真正跑起来之前就被判定失步退出，之后看到的大幅度移动其实是
// 退出后闭环自己的卡滞助推/giveup在打，不是蠕行在工作。先把爬升时间
// 拉长，给起步阶段更多余量，速度(150°/s)和失步阈值(90°)不动，只改
// 这一个变量看蠕行能不能真正跑起来。
#define FOC_POS_CREEP_RAMP_MS         1500U    // 进入蠕行时角速度从0爬到目标值的时长，避免瞬间速度阶跃
// 退出蠕行角度平滑过渡(用户主导决策，真正对症的修复)：之前两次真实
// 冲击/剧烈转动的根因是foc_theta的角度来源在退出那一拍瞬间切换(上一拍
// 还是蠕行自己开环推算的值，下一拍直接变成霍尔实测值)——观测坐实过
// 实测电流(1.17A)明显超过给定值(0.7A)，说明问题出在电流环的D/Q坐标系
// 被这一下角度突变搞错，不是外环的iq_target方向对不对(那是giveup/屏障
// 单向锁管的范围，管不到这一层)。退出蠕行那一刻不再让ISR瞬间切换角度
// 来源，而是给这么久的过渡时间，按矢量平均(不是简单线性平均——角度是
// 环形量，线性平均在跨0°/360°时会算错)从蠕行冻结住的起点角度平滑过渡
// 到霍尔实时角度，见main.c里ISR部分的具体实现。
#define FOC_POS_CREEP_ANGLE_BLEND_MS  30U      // 退出蠕行时角度平滑过渡时长(ms)
// 用户主导决策：反复实测坐实"退出蠕行后转速突然变快、持续数百ms才降
// 下来"这个现象的真正根因——蠕行只给恒定电流(FOC_POS_CREEP_IQ)，不是
// 恒定转速，150°/s这个"速度"其实只用来算参考角度/判断失步，从没真正
// 限制过转子实际能跑多快。遇到齿槽阻力小的路段，转子会在这个恒定电流
// 下自由加速，实测蠕行期间erpm_now经常已经冲到1000~1800，远超150°/s
// 折算的~650eRPM。退出那一刻转子带着这份真实动能，配合闭环本身刻意
// 偏保守的刹车强度(这个session更早验证过的设计选择，用"停得慢"换
// "停得稳")，自然要刹一阵子——不是bug，是"蠕行不限速"和"闭环故意慢
// 刹车"这两个各自合理的设计撞在一起。给蠕行本身补一个转速上限，从源头
// 别让它攒这么多超出预期的动能：沿蠕行方向的转速一旦超过这个值，直接
// 撤矩(不新增反向刹车力度，只是不再继续加力)，等降回上限以内再恢复
// 正常蠕行电流。150°/s对应约650eRPM(150*26/6)，上限先取1.5倍留一点
// 余量，不会紧到跟正常蠕行波动打架。
#define FOC_POS_CREEP_SPEED_CAP_ERPM  1000.0f  // 蠕行沿方向转速上限(eRPM)，超过就撤矩
// ↓↓↓ 用户主导决策：0.5A实测"一直在蠕动，没有前进"——蠕行是开环同步
// 跟踪，没有反馈校正兜底"迟早追上"，跟闭环卡滞助推那套"电流不够就多等
// 一会儿总能压过去"完全不同：给定速度下转矩不够同步裕量，转子会持续
// 失步/打滑，表现为原地小幅抖动而不是净前进，参考角度却一直在推进——
// 这跟desync检测的"位置差持续增长"设计初衷不完全一致(失步后转子跟着
// 小幅挪动、位置差不一定能稳定超过阈值)，根子是转矩裕量不够，不是
// 检测灵敏度问题。对比开机I-F启动这个已验证能可靠同步的参照点：那里
// 用FOC_IQ_REF=1.0A、稳态电频率6Hz(换算机械角速度约83°/s，比这里
// 60°/s还快)，说明1.0A在更快的速度下都能可靠同步，0.5A对60°/s明显
// 电流裕量不够。先对齐到这个已验证的电流量级复测，比继续猜低速度更
// 直接。
// ↓↓↓ 用户主导决策：1.0A(配合快速率斜坡+去掉iq_cap钳位后)实测已经能
// 连续转动，但有较大震动(用户确认"轻微，能接受"，未触及冲击线，可以
// 继续调参)。持续震动(不是进入蠕行那一瞬间的transient，是稳态旋转
// 全程都在抖)是同步电机常见现象——转矩越大，"参考角度-实测角度"这个
// 虚拟弹簧就越硬，裕量足够大时容易变成欠阻尼，转子绕着推进中的参考角
// 来回打转(hunting)而不是平滑跟随，不是失步/丢步。既然现在"电流能不能
// 送到位"这层bug已经修完(专用快速斜坡+不再被iq_cap基线钳掉)，没必要
// 再顶着1.0A这个startup同款的量级，往下降一档试试震动会不会减轻——
// 这跟找"能可靠同步的最低电流"是同一个方向，不是重新退回"送不到位"
// 那个坑(送不到位的问题在斜坡/钳位那两处，不在电流数值本身)。
#define FOC_POS_CREEP_IQ              0.7f     // 蠕行阶段的电流限幅(A)，简单限幅、不跑完整速度PI
#define FOC_POS_CREEP_DESYNC_DEG_E    90.0f    // 参考角度与霍尔实测角度的电角度差超过这个值才算失步嫌疑
#define FOC_POS_CREEP_DESYNC_MS       200U     // 失步嫌疑要持续这么久才真正判定失步、退出蠕行(去抖)

// ===== 到位判定 + RTT指令接口 =====
// 到位容差原计划±2°，规划阶段核查发现不可行：位置反馈rotor_pos_rad_e
// 每次霍尔跳变才整扇区累加一次(见FOC_HallEdge里"+= dir * sector_width_rad"
// 那行)，本质是60°电角度的粗量化计数器，不是连续测量值。±30°是MOTOR_
// POLE_PAIRS曾经错填成1时定的("半个60°机械角扇区")——极对数改成26
// (实测确认)之后，一个扇区只对应60°/26≈2.31°机械角，真实量化地板是
// 半扇区≈1.15°，比当初设想细26倍。±30°现在过于宽松，收紧到5°：留了
// 约4倍于地板的余量，既明显收紧、又不会紧到跟量化噪声打架导致"到位"
// 状态来回抖动进出。后续要再提精度得加编码器等更细的位置传感硬件。
#define FOC_POS_ARRIVE_TOL_DEG   5.0f    // |实时pos_err|小于此值才算进入到位窗口
#define FOC_POS_ARRIVE_MS        500U    // 到位窗口内持续这么久才判定为真到位(去抖，风格同FOC_IQ_SETTLE_MS)

// 行程软限位(用户要求)：转子实际位置(pos_now_deg，不是指令pos_target_deg)
// 一旦到达/超过这个值，禁止任何来源的转矩继续朝正方向叠加，只挡这一个
// 方向、不新增刹车方向的转矩权限，见下面应用处的详细说明。当前只在正
// 方向设限(用户明确要求"不超过500")，负方向暂不受影响。这是纯软件层面
// 的安全网，不是真正机械限位的替代品——接实际夹爪/负载后仍需要额外的
// 物理限位或更完善的双向限位逻辑。
#define FOC_POS_TRAVEL_LIMIT_DEG 500.0f
// 用户主导决策：先专注验证台阶问题(固定限幅电流扫描)，行程软限位暂时
// 关掉——500°的硬截停会在扫描测试里跟"台阶"这个现象混在一起(转子冲到
// 500被强制砍断，跟真正齿槽卡滞/电流不够导致的台阶看起来很像，但成因
// 完全不同，会污染这轮判断)。置0关闭，只在main.c应用处的判据里加一道
// 门槛，宏本身/数值不变，随时可以改回1恢复限位——台阶问题验证清楚、
// 准备做真正的大距离/带载测试之前必须改回1，这是接实际负载前的最后
// 一道软件安全网，不能长期关着。
// ↓↓↓ 用户主导决策：关掉期间复现过"持续反转、越来越远离目标"(固定限幅
// 第一版对称覆盖iq_cap导致，已修复)——事后复盘，那次没有任何东西兜底
// 正是因为这道限位当时是关的。转去做蠕行模式实验时先改回1恢复限位，
// 验证过失步保护(蠕行desync检测+快速回退闭环)工作正常、震动也调到
// 用户确认"轻微能接受"之后，现在测试目标是1080°，500°的限位会把行程
// 拦腰截断——用户主导决策松开限位，让转子能测到完整的1080°目标。
// ↓↓↓ 用户主导决策：蠕行退出瞬间实测坐实两次真实冲击(第二次连补了固定
// 屏障都没压住)，已完全关闭蠕行模式(FOC_POS_CREEP_DIAG=0)回退到纯闭环
// 路径——蠕行本身的desync检测这道保护随之一起失效，重新改回1，行程
// 限位是当前退回状态下唯一还在的最外层安全网，不能再关。
#define FOC_POS_TRAVEL_LIMIT_DIAG 1     // 置1启用行程软限位，置0临时关闭

// RTT指令接口：复用printf已经在用的SEGGER RTT调试口(双向)，在同一个终端
// 里输入角度数值(度)+回车即可下发新目标，不需要新硬件/接线。
#define FOC_POS_CMD_BUF_LEN      16       // 够放"-12345.6"这种数值+结尾
#define FOC_POS_CMD_MAX_DEG      36000.0f // 纯粹防止乱码/损坏字节解析出离谱数值，不是机械行程限位
                                           // (当前空轴无机械限位；接实际夹爪要另加基于真实行程的限位)
// 上机排查发现J-Link RTT Viewer发送不会自动带\r/\n终止符(rxb诊断字段
// 验证过：发的字节数正好等于输入的数字字符数，没有多出终止符那1~2个
// 字节)，纯等终止符永远等不到。改成空闲超时兜底：缓冲区有内容、超过
// 这么久没收到新字节就当一行结束去解析，不依赖发送端有没有加终止符。
#define FOC_POS_CMD_IDLE_FLUSH_MS 300U

// 转矩给定上升速率(A/s)。动态限幅：|eRPM|低于阈值(判定为"危险区"，零速
// 附近霍尔信息不可靠)时改用慢得多的速率，让电流变化跟机械系统/霍尔插值
// 的响应能力匹配；阈值不能跟阶跃目标转速同量级，否则整个测试区间都被
// 判定成危险区，电机永远只能慢速率蹭，蹭到一半被负载/齿槽弹回来。
#define FOC_IQ_RAMP_A_PER_S 2.0f
#define FOC_IQ_RAMP_A_PER_S_SLOW    0.6f      // 危险区里用的慢速率(A/s)
#define FOC_IQ_RAMP_NEAR_ZERO_ERPM  400.0f    // |eRPM|低于这个值判定为危险区
// giveup_iq(见motion_guard.h)只是把iq_cap这个上限抬高，foc_iq_ref真正
// 追上去还是要走上面的慢速率——两层慢(giveup_iq本身还要等速度环PI积分
// 慢慢爬 + 这里的电流斜坡又慢速率追)叠在一起，实测出现过卡死状态贯穿
// 整段log(几十秒甚至更久)才挣脱的情况。giveup场景下真正挣脱那一下的
// 冲击已经由MotionGuard的挣脱冲击观测限速屏障单独兜底(不管电流爬多快
// 挣脱，屏障都会介入收紧)，没必要再让这层电流斜坡慢速率帮着拖时间，
// 于是giveup_active时单独换一档更快的速率，纯粹缩短"卡死当中"的等待，
// 不影响挣脱那一下本身的冲击防护。
#define FOC_IQ_RAMP_A_PER_S_GIVEUP 3.0f       // giveup_active时的专用速率(A/s)
// 用户主导设计：蠕行模式(FOC_POS_CREEP_*)实测"一直蠕动没有前进"，log
// 坐实根因——蠕行期间erpm多数时候接近0(转子没能同步跟上)，会一直命中
// 上面的危险区慢速率(0.6A/s)，从上一次失败留下的~0.4A爬到蠕行目标
// (FOC_POS_CREEP_IQ=1.0A)要将近1秒，但失步检测(90°电角度+200ms去抖)
// 在电流还没爬到位之前(实测log里foc_iq_ref多数停在r0.4附近)就已经把
// 蠕行判定失败退出了——是一个自我挫败的死循环：电流永远来不及证明自己
// 就被判定失败。参照giveup_active已有的"专用更快速率"先例，蠕行期间
// 同样单独换一档快速率，让电流真正有机会在失步判定生效前爬到蠕行目标。
#define FOC_POS_CREEP_IQ_RAMP_A_PER_S 3.0f     // 蠕行模式(pos_creep_active)时的专用速率(A/s)
// 加了mg=%u/%u/%u第三位(giveup_active)诊断后实测证实：上面这层电流斜坡
// 修复没能真正缩短卡死时长，真正的瓶颈在更上游——速度环PI积分项
// speed_integ按Ki*err*dt_s累加，实测某次giveup期间err稳定在-95eRPM，
// IqRef爬升速率约0.06A/s，跟Ki*err=0.0006*95≈0.057A/s几乎精确吻合，
// 说明iq_target(=Kp*err+speed_integ)本身长得慢，电流斜坡再快也没东西
// 可追。giveup_active时改成固定速率强制爬升(不再按Ki*err的量级累加，
// err小的场景也能稳定在可预期时间内爬到giveup_iq)，跟电流斜坡那层
// 同样的理由：挣脱那一下的冲击已经由挣脱冲击观测限速屏障单独兜底，
// 这里没必要为了"防止转矩突变"把giveup状态下的积分也压得很慢。
#define FOC_SPEED_INTEG_RAMP_A_PER_S_GIVEUP 1.0f  // giveup_active时speed_integ的强制爬升速率(A/s)
// 曾经在这个1kHz左右的主循环层面试过"检测到瞬时超速就跳过斜坡、直接
// 满幅反打刹车"去兜底过零冲击，但触发判据是单边沿瞬时测速——分辨率
// 只有60°，本身纹波就能到±2600甚至变号，阈值卡在纹波带里导致几乎
// 每拍都触发，反而做成了一个由测量噪声驱动的bang-bang振荡器。已经
// 整个换成FOC_HallEdge()里的"卡滞挣脱"急停(见FOC_BREAKAWAY_*)：
// 判据换成"上一段真的卡了很久+这一段突然冲很快"这个更specific的组合，
// 而不是单一瞬时阈值；反应点也从主循环搬到霍尔中断本身，快了一到两个
// 数量级，不用再等主循环下一轮才反应过来。

#define FOC_ANGLE_HZ       2.0f     // 开环电角频率(Hz)，仅 FOC_ANGLE_SRC=0 时有效
#define FOC_PWM_FREQ       20000.0f // 控制频率，与PWM同步

// ===== 死区补偿 =====
// 死区(500ns，见tim.c的DeadTime=85)是与电流大小无关的固定电压误差，但占
// 目标电压的比例在电流小、调制度低时被放大，是过零附近台阶/毛刺的主因。
// 需按电流方向补回：Δd = 2·Td·fsw·sign(I)，代入后 Δd = 0.02 (2%占空比)
#define DT_COMP_ENABLE     1
#define DT_COMP_DEADTIME_NS 500.0f
// 电流过零附近做线性过渡而不是硬 sign()：噪声底约0.2A，直接用sign(i)
// 突变会让补偿本身在零点附近来回跳变2%占空比，这个滞环宽度用来平滑掉。
#define DT_COMP_HYST_A     0.30f
#define DT_COMP_IFILT_A    0.3f     // 补偿用电流的一阶低通系数，抑制ADC噪声对占空比的直接冲击

// 角度来源：0=开环给定(仅调试用，验证Clarke/Park/反Park/SVPWM链路本身，
// 会跳过上电对齐和I-F启动)  1=霍尔插值出的真实转子角
#define FOC_ANGLE_SRC      1
// 霍尔扇区与转子磁极的安装相位差(度电角)，跑起来后调它使Id最接近0、|I|最小
#define FOC_HALL_OFFSET_DEG  0.0f
// 霍尔序列方向。实测本机正转时霍尔为 1->3->2，与标准表的正向顺序相反，故置1。
#define FOC_HALL_DIR_REV     1
// 开机自动对齐标定：强制θ=0并通Id电流把转子拉到已知位置，
// 读此时的霍尔状态即可算出安装偏移，免去手动试6个值。
#define FOC_AUTO_ALIGN     1
// 对齐用的Id电流(A)，要能克服静摩擦，否则转子拉不到0°、标出来的offset是随机数
#define FOC_ALIGN_CURRENT  2.0f
#define FOC_ALIGN_MS       1500     // 对齐保持时间，要够转子稳定下来
// 两段对齐：先拉到θ=90°再拉到θ=0，避免转子恰好停在180°电角的不稳定
// 平衡点(转矩∝sin(180°)=0)上纹丝不动、标出随机的offset。
#define FOC_ALIGN_PRESTEP_MS 600
// 对齐复现性自检：0°→120°→0°走一圈，落点必须回到同一个霍尔扇区，
// 比"手动上电多次对比"更可靠——强制制造了一次真实位移，结论是硬的。
#define FOC_ALIGN_VERIFY     1
// I-F 启动：起步阶段角度开环给定、电流仍闭环，把转子拉转起来；
// 一旦霍尔测到有效速度就切回真实角度，解决"角度要等霍尔跳变、
// 霍尔跳变又要转子先转"的鸡生蛋问题。
#define FOC_STARTUP_RAMP   1
#define FOC_STARTUP_HZ     6.0f     // 开环拉起的目标电频率
#define FOC_STARTUP_MS     2500     // 加速时长
#define FOC_STARTUP_MAX_MS 6000     // 超时仍未同步则放弃并报告
// 位置环场景专用：I-F开环把转子拉到FOC_STARTUP_HZ这个转速才判定同步，
// 若直接切换，转子还带着这份物理惯量，位置环接手那一刻看似目标=实际
// (误差为0)，但转子仍在按惯量继续往前冲，几毫秒内又跑出一大截——
// 实测最多摆动过3000多度才收敛回来(虽然全程没有冲击感，机械冲击这条
// 线没破，但不符合"完全静止直到用户下指令"这个预期)。切换前先让
// foc_ol_omega从当前转速线性降到0(仍是开环、电流环不受影响)，让转子
// 真正接近静止后再进入位置环。
#define FOC_STARTUP_DECEL_MS 800    // 交接给位置环前的开环减速时长
// 是否在I-F转起来之后重新测一遍霍尔偏移。置0直接沿用上电对齐的偏移
// (更可信)。置1有风险：I-F下转子滞后磁场一个负载角，若转子还在滑步，
// 矢量平均的模长趋近0、结果是随机数，故置1时必须过下面两道校验。
#define FOC_HALL_SPIN_CAL  0
// 旋转标定的一致性下限：|矢量和|/样本数，1.0=完全一致，0=纯随机。
#define FOC_SPIN_CAL_MIN_R   0.80f
// 旋转标定与上电对齐结果的最大容许分歧(度)，超过则判定旋转标定不可信。
#define FOC_SPIN_CAL_MAX_DIFF 45.0f
// 霍尔停止判定：超过这么多个控制周期没有跳变就认为已停转，速度清零
#define FOC_HALL_TIMEOUT_TICKS  20000U   /* 20000 tick @20kHz = 1s */
// 真超时(卡住超过上面这1秒)时的兜底自转频率(电Hz)：原来超时后角度直接
// 钉死在扇区中心不动，真实复现过"转子空载、没有任何机械限位，卡滞助推
// 一直在给0.4~0.6A却彻底不转"——根子就在这里：钉死不动的角度配合持续
// 给的Iq，等于给了一个静止磁场向量，电流确实在流但只会把转子"吸"在
// 原地当保持转矩，不会再产生任何真实转动，永远等不到下一次真实跳变，
// 跟没通电看起来一样，但其实一直在通电只是没有效果，是个自锁死区、
// 复位前都恢复不了。只要上层还有转矩意图(foc_iq_ref!=0)就用这个很慢
// 的频率让角度按方向主动自转(参考I-F启动同样是"角度主动推、电流闭环
// 兜底"的思路)，给电流一个真正在转的磁场去拖转子，而不是钉死等一个
// 永远不会来的边沿；一旦测到新的真实跳变，本分支立刻不再进入，交回
// 正常插值。没有转矩意图(foc_iq_ref==0)时原样保持在当前角度不动，
// 避免凭空自转造成误动作。设得很慢(1Hz)只是给一个能拖动转子的旋转
// 磁场，不是重新做一次I-F启动。
#define FOC_HALL_TIMEOUT_CREEP_HZ  1.0f
// 霍尔跳变间隔下限(tick)。转子停在扇区边界上抖动时会产生一串间隔只有
// 几个tick的跳变，代入 ω=60°/dt 会得到荒谬的速度(dt=2 → 约10万eRPM)，
// 且该值会一直锁存到下次跳变，任何下游的滤波都救不回来，必须在源头拒绝。
// 4 tick = 200us，对应 5万 eRPM，远高于本机实测上限(约1.5万)，不会误杀真跳变。
// 这个下限是"物理上不可能"的最后防线，卡死-挣脱循环里实测冲到
// 3000~12000eRPM的那些尖峰，dt都比4tick大得多，会被这道防线放行，
// 直接以50%权重(见下面hall_omega_filt滤波系数)混进滤波值，是sector
// width打印畸变、eRPM尖峰、进而牵动速度环/卡滞助推误判的共同根源。
// 光收紧这个下限治标不治本(总能找到一个真实的快速掠过案例卡在阈值
// 附近)，真正要卡的是下面 FOC_HALL_OMEGA_CLAMP_ERPM——不管dt多小，
// 换算出的单次瞬时转速本身设一个"这个应用场景不可能超过"的硬顶。
#define FOC_HALL_MIN_DT_TICKS   4U
// 单次跳变换算出的瞬时转速，超过这个值就判定为不可信尖峰(卡滞挣脱瞬间
// 一个异常短的dt被放大出来的假象，或残余的电气抖动)，直接钳位而不是
// 原样喂给hall_omega_filt/hall_alpha/位置累加。目标运行区间只有±1500，
// 2倍裕量到3000，兜得住正常动态超调，但挡住了实测反复出现的
// 4000~12000那一档失真值。
#define FOC_HALL_OMEGA_CLAMP_ERPM  3000.0f
// 角加速度估计的钳位(rad/tick^2)，防止两次omega差分时分母(dt)偶然很小、
// 把噪声放大成离谱的加速度估计。按实测空载加速度约7700eRPM/s换算：
// 7700eRPM/s ≈ 806 rad/s^2 ≈ 2.0e-6 rad/tick^2(20kHz)，留7~8倍裕量给
// 反转这种更剧烈的瞬态，未来发现不够用再按实测数据调大。
#define FOC_HALL_ALPHA_MAX      1.5e-5f
// ---- 卡滞挣脱急停：从主循环搬到霍尔中断本身 ----
// 之前在主循环(约1kHz)里试过"瞬时转速超过阈值就刹车"，两个问题都在于
// 反应太粗：判据是单一瞬时阈值(碰上正常纹波就误触发，见下面主循环
// 斜坡那段的说明)，反应点也要等主循环下一轮才生效——真正的失控在
// 霍尔跳变之间就已经发生，等主循环反应过来时往往已经晚了几个跳变。
// 这里换一种更specific的判据、搬到反应最快的地方(霍尔跳变本身)：
// 上一段跳变的dt很大(说明真的卡了一阵，不是正常纹波)，紧接着这一段
// 跳变的瞬时转速又冲得很高(说明是卡滞挣脱冲出去了)——这两个条件同时
// 成立才触发，缺一不可，不会被单纯的高速巡航或普通纹波误触发。触发后
// 直接把foc_iq_ref清零(不是反打)：撤掉驱动它继续窜的转矩，让它凭
// 摩擦/反电动势自己降速，主循环的斜坡下一轮会从0重新平滑爬升，
// 不会像之前"满幅反打"那样又引入一次新的转矩阶跃。
#define FOC_BREAKAWAY_STALL_DT_TICKS  3000U    // 上一段跳变dt超过这个值(150ms)才算"真卡过"
#define FOC_BREAKAWAY_OMEGA_ERPM      1500.0f  // 挣脱后这一段瞬时转速超过这个值才算"冲出去了"
// 挣脱冲击观测限速屏障(MotionGuard新增第二层防护)：上面的急停只在挣脱那
// 一个霍尔中断里把foc_iq_ref清零一次，是单次瞬时动作，拦不住主循环下一拍
// 立刻按(可能仍然很大的)位置误差重新算出满量级speed_ref/iq_cap——相当于
// 急停完立刻又给了全力指令。这里在挣脱事件后追加一段(BARRIER_HOLD_MS)
// 临时收紧的限速/限流上限，按挣脱瞬间观测到的转速幅度分级(挣脱越猛压得
// 越死)，到点自动解除，交给MotionGuard_Update里的severity换算。
#define FOC_BARRIER_BASE_ERPM      400.0f   // severity=1时的屏障限速基准(eRPM)，起点值，待实测调整
#define FOC_BARRIER_BASE_IQ        0.6f     // severity=1时的屏障限流基准(A)，与FOC_STALL_KICK_IQ同量级(已验证手感)
#define FOC_BARRIER_SEVERITY_MAX   3.0f     // 限速/限流力度按挣脱速度加严的上限倍数，防止极端尖峰把上限压到接近0
#define FOC_BARRIER_HOLD_MS        800U     // 屏障维持时长，到点自动解除
// 卡滞助推/giveup"诊断退出"专用的固定severity：这两条退出路径的判据本身
// 就是erpm_now刚过kick_erpm(30)这个很低的阈值，如果沿用上面"按erpm_now
// 算severity"那套逻辑，severity必然落到1.0下限、barrier_iq_cap算出来
// 正好等于kick_iq(0.6A)/giveup_iq(0.5A)，等于没收紧——实测坐实：退出
// 那一刻mg从1/0/0变0/1/0，转子却带着攒的动能继续冲了约1380°，全程
// edges的kick/giveup标记都是0(退出那一刻状态已经翻转)，屏障没有真正
// 收紧过。2.0换算成0.3A/200eRPM，比kick_iq/giveup_iq明显更紧，起点值
// 待实测调整。
#define FOC_BARRIER_KICK_EXIT_SEVERITY 2.0f
// 置1：统计并打印六个霍尔扇区各自的实际宽度(电角度)。
// 插值假定每个扇区都是60°，若传感器安装角不均匀则不成立。
// 判读：转速稳定时六个数应都接近60°；实测偏差超过±5°就说明
// 插值的角度存在6倍电频率的周期性误差，是Iq摆动的来源。
#define FOC_HALL_SECTOR_DIAG    1
#define FOC_SECTOR_DIAG_MS      3000     // 打印间隔
// 扇区宽度合法性检查(用户主导设计)：实测剧烈反复换向场景下打印出过
// h4=223.7°这类离谱值，用于判断"这一轮打印窗口内的扇区宽度分布是否
// 可信"。注意：这里检查的是下面打印用的"360°*该扇区平均耗时占比"这个
// 归一化统计量，不是逐次跳变的瞬时角度(位置环用来累加rotor_pos_rad_e
// 的sector_width_rad是开机标定的固定查表值，不受这里影响，也不会因为
// 这个检查而跳变)——这个统计量只有在窗口内转速基本恒定时才等价于真实
// 扇区宽度；剧烈换向导致窗口内转速极不均匀时，哪怕霍尔信号完全正常，
// 单纯因为某个扇区恰好被"卡"在低速/反向那段时间里，也会把它的耗时占比
// 冲到远高于60°的离谱值，这是统计方法本身在非稳态下的已知局限，不
// 一定代表真实的霍尔信号损坏/EMI干扰。这个检查的意义是标记"这一轮的
// 扇区宽度数字本身不可信，不能拿来评价插值精度"，需要靠后续多次复测
// (稳态/剧烈换向分别测)才能进一步区分是统计伪影还是真实硬件问题。
#define HALL_SECTOR_MIN_DEG     35.0f
#define HALL_SECTOR_MAX_DEG     90.0f

// 霍尔边沿高精度时间戳：定时器输入捕获，阶段1(用户主导设计，见项目plan
// 文件对应章节的完整说明)。TIM3 CH1/CH2/CH3接HALL_U/V/W，双边沿捕获，
// 硬件在电平跳变那一刻直接锁存CNT，不受EXTI软件响应延迟/抖动影响，
// 1µs分辨率(比现有foc_tick的50µs细50倍)。这一阶段纯诊断旁路：跟原有
// EXTI触发的FOC_HallEdge()完全并存，不接入任何控制逻辑，只是把TIM3
// 捕获到的"精细dt"跟同一时刻foc_tick算出来的"粗dt"打印出来对比，供
// 判断精细时间戳是否可信、后续要不要真的接入FOC_HallEdge()用(阶段2)。
#define FOC_HALL_TIM3_DIAG      1
// 用户主导决策：实测上机复现"RTT打印卡死/乱码"——这个session更早已经
// 验证过RTT乱码的根因是打印速率长期超过RTT实际吞吐能力(见[HALL]扇区
// 诊断FOC_SECTOR_DIAG_MS=3000这条同样的节流先例)，[TIM3IC]这行原来
// 跟主[FOC]行共用330ms节奏，是新增的额外打印负载，叠加原有[FOC]/
// [STAT]/[HALL]之后又把总打印量推过了阈值。改成独立节流，间隔拉长到
// 2000ms，跟扇区诊断的节流是同一个道理、同一套机制(last_xxx_print+
// 独立interval对比)。
#define FOC_TIM3IC_DIAG_MS      2000
// 置1：在20kHz上统计Id/Iq的均值与极值，随每行FOC打印一起输出。
// 每330ms打印一个瞬时快照无法判断跟随质量——那一个样本既可能是
// 真实波动也可能是噪声。均值贴住给定=环在工作，均值偏离=跟随失败。
#define FOC_CURRENT_STATS       1

// 诊断"挣脱过冲"用：卡滞助推刚触发(0->1沿)的那一刻，临时把下面[FOC]
// 周期打印的间隔从330ms降到FOC_KICK_FASTPRINT_MS，维持FOC_KICK_FASTPRINT_
// WINDOW_MS这么久后自动恢复正常间隔——正常330ms间隔下20kHz控制环两次
// 打印之间能跑6600多个周期，挣脱-加速-刹车这类几百ms内完成的过程会被
// 日志颗粒度整个盖住，看不出内部到底发生了什么。这里不改任何控制逻辑
// (kick_iq/kick_erpm/arm_ms都不动)，只是把打印变密，问题定位清楚后可以
// 关掉。
// 曾经把BUFFER_SIZE_UP从1024加到4096、FASTPRINT_MS从5拓宽到10ms，试图
// 缓解乱码，但实测发现对"长时间真卡死"这类场景没用：stall_kicking在
// mg=1/0和0/0之间反复横跳，每次0->1沿都会把fast_print_until_ms重新顶满
// 一整个WINDOW_MS，只要横跳间隔小于WINDOW_MS，密集打印就会被连续续期、
// 长时间几乎不间断地维持10ms一行——这已经不是缓冲区多大的问题，是
// 持续打印速率长期超过RTT实际吞吐能力，加多大缓冲区都只是拖延写爆。
// 加一个COOLDOWN_MS：距离上一次真正顶满窗口不足这么久，即使又检测到
// 0->1沿也不再重新顶满(但不影响卡滞助推本身的控制逻辑，只是不重新
// 描述这段时间的细节)，把密集打印的占空比压下来，让RTT有喘息时间。
// ↓↓↓ 用户主导决策：现在关掉了行程软限位(FOC_POS_TRAVEL_LIMIT_DIAG=0)
// 专门验证台阶问题，转子到终点前可能连续经历很多次卡滞/挣脱循环，密集
// 窗口被反复顶满、长时间维持10ms一行，COOLDOWN_MS压不住这种量级的循环
// 频率，实测复现"RTT乱码+卡死"。现在这轮关心的是"整段行程有没有台阶"
// 这个趋势性问题，不是单次挣脱transient的精细时序，用不上这个诊断，
// 先关掉换回正常330ms周期打印。台阶问题验证清楚、要回头精细分析某一次
// 具体挣脱transient时，改回1。
#define FOC_KICK_FASTPRINT_DIAG      0
#define FOC_KICK_FASTPRINT_MS        10U
#define FOC_KICK_FASTPRINT_WINDOW_MS 1000U
#define FOC_KICK_FASTPRINT_COOLDOWN_MS 3000U

// ===== VOFA+ 波形输出 =====
// 经USART2(PB3/PB4)直连USB转TTL模块发 FireWater 格式："v1,v2,v3\n"。
// VOFA+ 设置：串口 / 对应COM口 / 波特率与 VOFA_BAUD 一致 / 数据引擎选 FireWater
#define VOFA_OUTPUT        1
#define VOFA_BAUD          460800   // 9600太慢画不了波形
// 每帧至少攒够这么多个20kHz样本再发、取均值，与波特率/主循环速度解耦，
// 兼做抗混叠滤波。625帧/秒(32样本)@50Hz电频率约12.5点/周期，形状不失真；
// 降太低(如100帧/秒)会卡在奈奎斯特极限附近、混叠成锯齿。VOFA+软件侧偶发
// 的~2秒画面滞后跟这个值无关，是软件侧缓冲/渲染问题，重启VOFA+即可。
#define VOFA_MIN_SAMPLES   32

// 电机极对数，用于把电频率换算成机械转速：机械RPM = eRPM / 极对数
// 之前一直按1(未验证的默认值)在跑。用Hall_SelfTest()新加的pulse_cnt
// 实测(手转一圈数霍尔跳变次数：一圈的跳变数=极对数×6)，用户确认真实值
// 是26——这跟原来的1相差26倍，意味着本session此前所有以"度"为单位的
// 现象描述(pos_now_deg/pos_target_deg都是拿rotor_pos_rad_e除以这个宏
// 换算出来的)全部被夸大了26倍：之前看到的"过冲几千度"，物理上可能只是
// 几十度；早前反复出现又被搁置的"pos虚高"疑点(标记法观察转的圈数比pos
// 显示的少很多)，根子很可能就在这里。同理，霍尔60°电角度对应的机械角
// 只有60/26≈2.3°，"霍尔60°粗量化决定位置环精度天花板、±30°是能做到的
// 最好精度"这条贯穿整个session的假设也是建立在错误极对数上的，实际
// 量化粒度比想象中细得多。这个宏改动后，pos_now_deg/pos_target_deg以及
// 轨迹发生器的加减速度/最大速度(FOC_POS_TRAJ_ACCEL_DEG_S2/VMAX_DEG_S，
// 公式里已经除以MOTOR_POLE_PAIRS)会自动按正确比例变化，但所有硬编码成
// 具体"度数"数值、按旧的(错误)标定手感调出来的常量——尤其
// FOC_POS_ARRIVE_TOL_DEG/FOC_POS_KICK_SCALE_DIST_DEG/
// FOC_POS_GIVEUP_SCALE_DIST_DEG/FOC_POS_TRAJ_KP_ERPM_PER_DEG这几个——
// 全部需要重新审视，不能直接沿用，否则等于拿26倍失真的标定去套正确的量。
#define MOTOR_POLE_PAIRS   26

// ===== 保护阈值 =====
// 任一相电流超过此值立即停机(20kHz中断里检查，见FOC_Update)。
#define OL_TRIP_AMP        6.0f

// 数据口：不再接RS485收发器，USART2(PB3/PB4)直接接USB转TTL模块到电脑，
// 点对点全双工，不需要方向使能/收发切换。
#define VOFA_UART          (&huart2)
/* USER CODE END PD */

